def first_repeating_char(s):
    for ch in s:
        if s.count(ch) > 1:
            return ch
    return None

def count_substring_occurrences_overlapping(s, sub):
    if sub == "":
        return 0
    count = 0
    start = 0
    while True:
        idx = s.find(sub, start)
        if idx == -1:
            break
        count += 1
        start = idx + 1
    return count

def is_balanced_parentheses(s):
    depth = 0
    for ch in s:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

def reverse_vowels(s):
    vowels = "aeiouAEIOU"
    chars = list(s)
    l, r = 0, len(chars) - 1
    while l < r:
        if chars[l] not in vowels:
            l += 1
        elif chars[r] not in vowels:
            r -= 1
        else:
            chars[l], chars[r] = chars[r], chars[l]
            l += 1
            r -= 1
    return ''.join(chars)

def is_isogram(s):
    letters = [ch.lower() for ch in s if ch.isalpha()]
    return len(letters) == len(set(letters))

def word_wrap(s, width):
    words = s.split()
    lines = []
    current = ""
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += " " + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    return lines

def is_valid_identifier(s):
    import string
    if not s:
        return False
    allowed = string.ascii_letters + string.digits + '_'
    if s[0] not in string.ascii_letters + '_':
        return False
    return all(ch in allowed for ch in s)

def toggle_case_by_index(s):
    out = []
    for i, ch in enumerate(s):
        out.append(ch.upper() if i % 2 == 0 else ch.lower())
    return ''.join(out)

def longest_run(s):
    if not s:
        return ("", 0)
    best_char = s[0]
    best_len = 1
    cur_char = s[0]
    cur_len = 1
    for ch in s[1:]:
        if ch == cur_char:
            cur_len += 1
        else:
            cur_char = ch
            cur_len = 1
        if cur_len > best_len:
            best_len = cur_len
            best_char = cur_char
    return (best_char, best_len)

def collapse_whitespace(s):
    import re
    return re.sub(r'\s+', ' ', s.strip())

def count_sentences(s):
    import re
    parts = re.split(r'[.!?]+', s)
    return sum(1 for p in parts if p.strip())

def is_palindrome_ignore_non_alnum(s):
    filtered = [ch.lower() for ch in s if ch.isalnum()]
    return filtered == filtered[::-1]

def longest_common_prefix(strs):
    if not strs:
        return ""
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix
